  keyIngredients?:
    | {
        name: string;
        text?: string | null;
        id?: string | null;
      }[]
    | null;
  fullIngredients?: string | null;
  meta?: {
    title?: string | null;
    description?: string | null;
    image?: (number | null) | Media;
  };
  /**
   * Used in the URL. Leave blank to generate from the title.
   */
